package com.logiplatform.repository; import com.logiplatform.model.WarehouseTask; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface WarehouseTaskRepository extends JpaRepository<WarehouseTask,UUID>{List<WarehouseTask> findAllByTenantIdAndWarehouseIdOrderByCreatedAtDesc(UUID t,UUID w); List<WarehouseTask> findAllByTenantIdAndStatusOrderByDueAtAsc(UUID t,String s); Optional<WarehouseTask> findByIdAndTenantId(UUID id,UUID t);}